def parse(tree):
    val, left, right = [tree[0]], [-1], [-1]
    i, u = 1, 0
    while u < len(val) and i < len(tree):
        for kids in (left, right):
            if i < len(tree):
                x = tree[i]
                i += 1
                if x != -1:
                    kids[u] = len(val)
                    val.append(x)
                    left.append(-1)
                    right.append(-1)
        u += 1
    return val, left, right


def bestRootedCluster(tree, k):
    val, left, right = parse(tree)
    n = len(val)
    dp = [None] * n
    for u in range(n - 1, -1, -1):
        cur = [-1, val[u]]
        for c in (left[u], right[u]):
            if c == -1:
                continue
            d = dp[c]
            dp[c] = None
            lc, ld = len(cur) - 1, len(d) - 1
            m = min(lc + ld, k)
            new = cur[:min(lc, k) + 1] + [-1] * (m - min(lc, k))
            for j in range(1, lc + 1):
                base = cur[j]
                for t in range(1, min(ld, k - j) + 1):
                    cand = base + d[t]
                    if cand > new[j + t]:
                        new[j + t] = cand
            cur = new
        dp[u] = cur
    return dp[0][k]
